import urllib.request, json, base64, io
import numpy as np
from PIL import Image
URL='http://loophole-sim:8000/mcp'
class C:
    def __init__(self):
        self.sid=None; self.id=0
    def _post(self, method, params=None, notify=False):
        h={"Content-Type":"application/json","Accept":"application/json, text/event-stream"}
        if self.sid: h["Mcp-Session-Id"]=self.sid
        b={"jsonrpc":"2.0","method":method}
        if not notify:
            self.id+=1; b["id"]=self.id
        if params is not None: b["params"]=params
        req=urllib.request.Request(URL,data=json.dumps(b).encode(),headers=h,method="POST")
        r=urllib.request.urlopen(req,timeout=30)
        s=r.headers.get("Mcp-Session-Id")
        if s: self.sid=s
        raw=r.read(); ct=r.headers.get("Content-Type","")
        if "text/event-stream" in ct:
            parts=[]
            for line in raw.decode().splitlines():
                if line.startswith("data:"): parts.append(line[5:].strip())
            raw="\n".join(parts).encode()
        return json.loads(raw) if raw.strip() else None
    def init(self):
        self._post("initialize",{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"c","version":"0"}})
        self._post("notifications/initialized",{},notify=True)
    def tool(self, name, args=None):
        r=self._post("tools/call",{"name":name,"arguments":args or {}})
        return r
def parse_render(res):
    # res is jsonrpc result: {content:[{type:text,text:caption},{type:image,data:..,mimeType}...]}
    out={"caption":None,"images":[]}
    content=res["result"]["content"]
    for c in content:
        if c.get("type")=="text":
            out["caption"]=json.loads(c["text"])
        elif c.get("type")=="image":
            img=np.array(Image.open(io.BytesIO(base64.b64decode(c["data"]))))
            out["images"].append(img)
    return out
