    i=np.floor((pts-lo)/res).astype(int);i=np.clip(i,0,dims-1)
    return dist[i[:,0],i[:,1],i[:,2]]
def mind(pose):
    Rp=R.from_quat([pose[4],pose[5],pose[6],pose[3]]).as_matrix()
    return float(sdf(Bl@Rp.T+pose[:3]).min())
def qmul(a,b):
    w1,x1,y1,z1=a;w2,x2,y2,z2=b
    return np.array([w1*w2-x1*x2-y1*y2-z1*z2,w1*x2+x1*w2+y1*z2-z1*y2,w1*y2-x1*z2+y1*w2+z1*x2,w1*z2+x1*y2-y1*x2+z1*w2])
def qnorm(q):return q/np.linalg.norm(q)
def rand_pose(anchor,cell,rotscale):
    dp=np.random.randn(3)*cell
    dq=R.from_rotvec(np.random.randn(3)*rotscale).as_quat()
    q=qnorm(qmul(anchor[3:],np.array([dq[3],dq[0],dq[1],dq[2]])))
    return np.concatenate([anchor[:3]+dp,q])
def interp(pa,pb,t):
    p=pa[:3]+(pb[:3]-pa[:3])*t
    qa=R.from_quat([pa[3],pa[4],pa[5],pa[6]]);qb=R.from_quat([pb[3],pb[4],pb[5],pb[6]])
    q=Slerp([0,1],R.concatenate([qa,qb]))(t).as_quat()
    return np.concatenate([p,[q[3],q[0],q[1],q[2]]])
DIRS=None
