    global DIRS;vs=[]
    for i in range(n):
        y=1-2*(i+0.5)/n;r=np.sqrt(max(0,1-y*y));th=np.pi*(1+5**0.5)*i
        vs.append([r*np.cos(th),y,r*np.sin(th)])
    DIRS=np.array(vs)
