import sys;sys.path.insert(0,'/tmp/opencode')
from planf import *
import numpy as np,time,os
t0=time.time();BUDGET=float(os.environ.get("BUDGET","100"))
pos=np.load("pose_b.npy");q=np.load("quat_b.npy");cur=np.concatenate([pos,q])
print("cur mind",round(mind(cur),4),flush=True)
# load checkpoint
if os.path.exists("nodes.npy"):
    data=np.load("nodes.npy");nodes=list(data["nodes"]);parents=list(data["parents"])
    print("resumed nodes",len(nodes),flush=True)
else:
    nodes=[cur.copy()];parents=[-1]
def edge_free(a,b,st=10,thr=0.004):
    for i in range(1,st+1):
        if mind(interp(a,b,i/st))<thr:return False
    return True
goal=None;gdir=None;it=0
while time.time()-t0<BUDGET:
    it+=1
    r=np.random.rand()
    bi=np.random.randint(len(nodes));base=nodes[bi]
    if r<0.6: cand=rand_pose(base,0.18,0.4)
    elif r<0.85:
        d=DIRS[np.random.randint(len(DIRS))];cand=base.copy();cand[:3]=base[:3]+d*(0.1+np.random.rand()*0.5);cand=rand_pose(cand,0.08,0.45)
    else: cand=rand_pose(base,0.35,0.6)
    if mind(cand)<0.004:continue
    if not edge_free(base,cand):continue
    nodes.append(cand);parents.append(bi);ni=len(nodes)-1
    if it%3==0:
        ed=escape_dir(cand)
        if ed is not None:
            goal=ni;gdir=ed;print("ESCAPE it",it,"t",round(time.time()-t0,1),flush=True);break
    if it%2000==0:print(it,"nodes",len(nodes),"t",round(time.time()-t0,1),flush=True)
np.savez("nodes.npy",nodes=np.array(nodes),parents=np.array(parents))
print("END it",it,"nodes",len(nodes),"goal",goal,"t",round(time.time()-t0,1),flush=True)
if goal is not None:
    path=[];i=goal
    while i!=-1:path.append(nodes[i]);i=parents[i]
    path=path[::-1];np.save("path5.npy",np.array(path));np.save("gdir5.npy",gdir)
    print("PATH nodes",len(path),flush=True)
